def transform(grid):
    divider = next(i for i, row in enumerate(grid) if all(v == 5 for v in row))
    counts = {}
    for color in (2, 4):
        above = sum(row.count(color) for row in grid[:divider])
        below = sum(row.count(color) for row in grid[divider + 1:])
        counts[color] = abs(above - below)
    color = 2 if counts[2] >= counts[4] else 4
    return [[color, color], [color, color]]
